_choice_path() {
    _argc_util_comp_path
}

_choice_run() {
    local dir="$PWD" parent
    while :; do
        if [[ -f "$dir/package.json" ]]; then
            jq -b -r '(.scripts // {}) | keys[]' "$dir/package.json" 2>/dev/null
            return 0
        fi
        parent="${dir%/*}"
        [[ -z "$parent" || "$parent" == "$dir" ]] && return 0
        dir="$parent"
    done
}

_choice_signal() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i <= NF; i++) {
            if ($i ~ /^SIG[A-Z][A-Z0-9]*$/) print $i
            else if ($i ~ /^[A-Z][A-Z0-9]*$/) print "SIG" $i
        }
    }'
}
